//! Unicode text segmentation and character properties for Kinogaki's text
//! editing and layout, from the Unicode Character Database (version
//! [`UNICODE_VERSION`]):
//!
//! - [`graphemes`] / [`grapheme_indices`]: extended grapheme clusters, the
//!   user-perceived characters a text cursor steps over (UAX #29 §3);
//! - [`word_bound_indices`]: the text split at every word boundary, words and
//!   the runs between them (UAX #29 §4);
//! - [`is_mark`]: combining marks (General_Category Mn, Mc or Me).
//!
//! The property tables (src/tables.rs) are generated by tools/generate.py
//! from the UCD files in ucd/; tests/tables.rs checks every code point against
//! those files and tests/conformance.rs runs the UCD's own break tests.

mod grapheme;
mod tables;
mod word;

pub use grapheme::{GraphemeIndices, Graphemes, grapheme_indices, graphemes};
pub use tables::UNICODE_VERSION;
pub use word::{WordBoundIndices, word_bound_indices};

/// Whether `c` is a combining mark: General_Category Mn (nonspacing),
/// Mc (spacing combining) or Me (enclosing).
pub fn is_mark(c: char) -> bool {
    let c = c as u32;
    c >= 0x300 && search(tables::MARKS, c, |&(a, b)| (a, b)).is_some()
}

/// The entry of `table` (sorted inclusive ranges) holding `c`.
#[inline]
fn search<T>(table: &[T], c: u32, range: impl Fn(&T) -> (u32, u32)) -> Option<&T> {
    let i = table.partition_point(|entry| range(entry).1 < c);
    table.get(i).filter(|entry| range(entry).0 <= c)
}

/// The value of `c` in a (first, last, value) table, 0 outside every range.
#[inline]
fn value(table: &[(u32, u32, u8)], ascii: &[u8; 128], c: char) -> u8 {
    let c = c as u32;
    if c < 128 {
        return ascii[c as usize];
    }
    search(table, c, |&(a, b, _)| (a, b)).map_or(0, |&(_, _, v)| v)
}
